import 'package:flutter/material.dart';
import 'package:responsive_framework/responsive_framework.dart';

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Auto Scale App',
      builder: (context, child) => ResponsiveBreakpoints.builder(
        child: child!,
        breakpoints: [
          // autoScale: 해당 범위에서 자동 스케일링
          const Breakpoint(
            start: 0,
            end: 450,
            name: MOBILE,
          ),
          const Breakpoint(
            start: 451,
            end: 800,
            name: TABLET,
          ),
          const Breakpoint(
            start: 801,
            end: 1920,
            name: DESKTOP,
          ),
        ],
      ),
      home: const HomePage(),
    );
  }
}

class HomePage extends StatelessWidget {
  const HomePage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('자동 스케일링')),
      // MaxWidthBox로 최대 너비 제한
      body: MaxWidthBox(
        maxWidth: 1200,  // 최대 너비
        child: ResponsiveScaledBox(
          width: 450,  // 기준 너비 (모바일 기준)
          child: _buildContent(),
        ),
      ),
    );
  }

  Widget _buildContent() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            '자동 스케일링 예시',
            style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 16),
          const Text(
            '화면 크기에 따라 모든 요소가 비율에 맞게 확대/축소됩니다. '
            '기준 너비 450px에서 디자인하면 다른 화면 크기에서도 '
            '동일한 비율로 표시됩니다.',
          ),
          const SizedBox(height: 24),
          // 카드 그리드
          GridView.count(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            crossAxisCount: 2,
            mainAxisSpacing: 16,
            crossAxisSpacing: 16,
            children: List.generate(4, (index) {
              return Card(
                child: Center(
                  child: Text('Item ${index + 1}'),
                ),
              );
            }),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:responsive_framework/responsive_framework.dart';

class ResponsiveScreen extends StatelessWidget {
  const ResponsiveScreen({super.key});

  @override
  Widget build(BuildContext context) {
    // 현재 브레이크포인트 확인
    final breakpoint = ResponsiveBreakpoints.of(context).breakpoint;
    final isMobile = ResponsiveBreakpoints.of(context).isMobile;
    final isTablet = ResponsiveBreakpoints.of(context).isTablet;
    final isDesktop = ResponsiveBreakpoints.of(context).isDesktop;

    // 화면 너비 (MediaQuery와 동일)
    final screenWidth = ResponsiveBreakpoints.of(context).screenWidth;

    return Scaffold(
      appBar: AppBar(
        title: Text('현재: ${breakpoint.name} (${screenWidth.toInt()}px)'),
      ),
      // 모바일에서만 Drawer 사용
      drawer: isMobile ? const Drawer(child: Text('모바일 메뉴')) : null,
      body: Row(
        children: [
          // 데스크톱/태블릿에서 사이드 네비게이션
          if (!isMobile)
            NavigationRail(
              extended: isDesktop,  // 데스크톱에서만 확장
              destinations: const [
                NavigationRailDestination(
                  icon: Icon(Icons.home),
                  label: Text('홈'),
                ),
                NavigationRailDestination(
                  icon: Icon(Icons.search),
                  label: Text('검색'),
                ),
                NavigationRailDestination(
                  icon: Icon(Icons.settings),
                  label: Text('설정'),
                ),
              ],
              selectedIndex: 0,
              onDestinationSelected: (_) {},
            ),

          // 메인 콘텐츠
          Expanded(
            child: _buildContent(context),
          ),
        ],
      ),
      // 모바일에서만 BottomNavigationBar
      bottomNavigationBar: isMobile
          ? BottomNavigationBar(
              items: const [
                BottomNavigationBarItem(icon: Icon(Icons.home), label: '홈'),
                BottomNavigationBarItem(icon: Icon(Icons.search), label: '검색'),
                BottomNavigationBarItem(icon: Icon(Icons.settings), label: '설정'),
              ],
            )
          : null,
    );
  }

  Widget _buildContent(BuildContext context) {
    final isDesktop = ResponsiveBreakpoints.of(context).isDesktop;
    final isTablet = ResponsiveBreakpoints.of(context).isTablet;

    // 브레이크포인트별 열 개수
    int crossAxisCount;
    if (isDesktop) {
      crossAxisCount = 4;
    } else if (isTablet) {
      crossAxisCount = 3;
    } else {
      crossAxisCount = 2;
    }

    return GridView.builder(
      padding: const EdgeInsets.all(16),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: crossAxisCount,
        mainAxisSpacing: 16,
        crossAxisSpacing: 16,
      ),
      itemCount: 12,
      itemBuilder: (context, index) {
        return Card(
          child: Center(
            child: Text('Item ${index + 1}'),
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:responsive_framework/responsive_framework.dart';

class ResponsiveValuesExample extends StatelessWidget {
  const ResponsiveValuesExample({super.key});

  @override
  Widget build(BuildContext context) {
    // 브레이크포인트별 패딩 값
    final padding = ResponsiveValue<double>(
      context,
      defaultValue: 16,  // 기본값
      conditionalValues: [
        const Condition.equals(name: MOBILE, value: 16),
        const Condition.equals(name: TABLET, value: 24),
        const Condition.equals(name: DESKTOP, value: 32),
      ],
    ).value;

    // 브레이크포인트별 폰트 크기
    final titleSize = ResponsiveValue<double>(
      context,
      defaultValue: 24,
      conditionalValues: [
        const Condition.smallerThan(name: TABLET, value: 20),
        const Condition.largerThan(name: TABLET, value: 32),
      ],
    ).value;

    // 브레이크포인트별 열 개수
    final columnCount = ResponsiveValue<int>(
      context,
      defaultValue: 2,
      conditionalValues: [
        const Condition.equals(name: MOBILE, value: 1),
        const Condition.equals(name: TABLET, value: 2),
        const Condition.equals(name: DESKTOP, value: 3),
        const Condition.largerThan(name: DESKTOP, value: 4),
      ],
    ).value;

    // 특정 브레이크포인트에서만 표시
    final showSidebar = ResponsiveValue<bool>(
      context,
      defaultValue: false,
      conditionalValues: [
        const Condition.largerThan(name: MOBILE, value: true),
      ],
    ).value;

    return Scaffold(
      appBar: AppBar(
        title: Text(
          '반응형 값',
          style: TextStyle(fontSize: titleSize),
        ),
      ),
      body: Row(
        children: [
          // 조건부 사이드바
          if (showSidebar)
            Container(
              width: 200,
              color: Colors.grey[200],
              child: const Center(child: Text('Sidebar')),
            ),

          // 메인 콘텐츠
          Expanded(
            child: Padding(
              padding: EdgeInsets.all(padding),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '브레이크포인트별 스타일',
                    style: TextStyle(
                      fontSize: titleSize,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  Text('패딩: $padding, 열: $columnCount'),
                  const SizedBox(height: 16),
                  Expanded(
                    child: GridView.builder(
                      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: columnCount,
                        mainAxisSpacing: 16,
                        crossAxisSpacing: 16,
                      ),
                      itemCount: 8,
                      itemBuilder: (context, index) {
                        return Card(
                          child: Center(child: Text('Item ${index + 1}')),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// 재사용 가능한 반응형 유틸리티
class ResponsiveUtils {
  static double getPadding(BuildContext context) {
    return ResponsiveValue<double>(
      context,
      defaultValue: 16,
      conditionalValues: [
        const Condition.equals(name: MOBILE, value: 16),
        const Condition.equals(name: TABLET, value: 24),
        const Condition.equals(name: DESKTOP, value: 32),
      ],
    ).value;
  }

  static int getGridColumns(BuildContext context) {
    return ResponsiveValue<int>(
      context,
      defaultValue: 2,
      conditionalValues: [
        const Condition.equals(name: MOBILE, value: 2),
        const Condition.equals(name: TABLET, value: 3),
        const Condition.equals(name: DESKTOP, value: 4),
      ],
    ).value;
  }

  static double getFontSize(BuildContext context, {required double base}) {
    final multiplier = ResponsiveValue<double>(
      context,
      defaultValue: 1.0,
      conditionalValues: [
        const Condition.equals(name: MOBILE, value: 1.0),
        const Condition.equals(name: TABLET, value: 1.1),
        const Condition.equals(name: DESKTOP, value: 1.2),
      ],
    ).value;
    return base * multiplier;
  }
}

import 'package:flutter/material.dart';
import 'package:responsive_framework/responsive_framework.dart';

// 적응형 레이아웃: 화면 크기에 따라 완전히 다른 레이아웃
class AdaptiveLayout extends StatelessWidget {
  final Widget mobileLayout;
  final Widget tabletLayout;
  final Widget desktopLayout;

  const AdaptiveLayout({
    super.key,
    required this.mobileLayout,
    required this.tabletLayout,
    required this.desktopLayout,
  });

  @override
  Widget build(BuildContext context) {
    if (ResponsiveBreakpoints.of(context).isDesktop) {
      return desktopLayout;
    } else if (ResponsiveBreakpoints.of(context).isTablet) {
      return tabletLayout;
    } else {
      return mobileLayout;
    }
  }
}

// 마스터-디테일 레이아웃
class MasterDetailLayout extends StatefulWidget {
  const MasterDetailLayout({super.key});

  @override
  State<MasterDetailLayout> createState() => _MasterDetailLayoutState();
}

class _MasterDetailLayoutState extends State<MasterDetailLayout> {
  int? _selectedIndex;

  final List<String> _items = List.generate(20, (i) => 'Item ${i + 1}');

  @override
  Widget build(BuildContext context) {
    final isWide = ResponsiveBreakpoints.of(context)
        .largerOrEqualTo(TABLET);

    if (isWide) {
      // 태블릿/데스크톱: 좌우 분할
      return Scaffold(
        appBar: AppBar(title: const Text('마스터-디테일')),
        body: Row(
          children: [
            // 마스터 (리스트)
            SizedBox(
              width: 300,
              child: _buildMasterList(),
            ),
            const VerticalDivider(width: 1),
            // 디테일
            Expanded(
              child: _selectedIndex != null
                  ? _buildDetailView(_items[_selectedIndex!])
                  : const Center(child: Text('항목을 선택하세요')),
            ),
          ],
        ),
      );
    } else {
      // 모바일: 스택 네비게이션
      return Scaffold(
        appBar: AppBar(title: const Text('목록')),
        body: _buildMasterList(),
      );
    }
  }

  Widget _buildMasterList() {
    return ListView.builder(
      itemCount: _items.length,
      itemBuilder: (context, index) {
        final isSelected = _selectedIndex == index;
        return ListTile(
          title: Text(_items[index]),
          selected: isSelected,
          onTap: () {
            final isWide = ResponsiveBreakpoints.of(context)
                .largerOrEqualTo(TABLET);

            if (isWide) {
              setState(() => _selectedIndex = index);
            } else {
              // 모바일에서는 새 화면으로
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => Scaffold(
                    appBar: AppBar(title: Text(_items[index])),
                    body: _buildDetailView(_items[index]),
                  ),
                ),
              );
            }
          },
        );
      },
    );
  }

  Widget _buildDetailView(String item) {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
            item,
            style: const TextStyle(fontSize: 32, fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 16),
          const Text('상세 내용이 여기에 표시됩니다.'),
        ],
      ),
    );
  }
}

// 반응형 그리드 레이아웃
class ResponsiveGridLayout extends StatelessWidget {
  final List<Widget> children;

  const ResponsiveGridLayout({super.key, required this.children});

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        // 화면 너비에 따른 열 개수 계산
        final width = constraints.maxWidth;
        int columns;
        if (width >= 1200) {
          columns = 4;
        } else if (width >= 900) {
          columns = 3;
        } else if (width >= 600) {
          columns = 2;
        } else {
          columns = 1;
        }

        return GridView.count(
          crossAxisCount: columns,
          mainAxisSpacing: 16,
          crossAxisSpacing: 16,
          padding: const EdgeInsets.all(16),
          children: children,
        );
      },
    );
  }
}

